 const m=ringPool.acquire(telegraphGeometries.get(range),enemy.avatar.group.position,heavy?0x70c7ee:0xf1b786,.23);
 m.position.y+=.07;
 m.rotation.set(Math.PI/2,0,Math.atan2(enemy.attackDir.z,enemy.attackDir.x));
