   shell(0,.04,.60,.225,.255,.83,metal);shell(0,.16,.49,.15,.13,.51,light);shell(0,-.22,0,.153,.32,.20,wrap).rotation.x=-.26;for(const z of [.63,.79,.95])shell(0,.06,z,.22,.21,.075,metal);
