 prophecy:[[.38,523,.13,1,'triangle'],[.44,659,.13,1,'sine',.09],[.52,784,.14,1,'triangle',.18],[.72,1046,.15,1.02,'sine',.28]],
 slowmo:[[.52,180,.28,.32,'sine'],[.42,900,.22,.22,'lowpass'],[.38,620,.12,.45,'triangle',.06]],
